/**
 * `agent-sdk init --from automation:<url>` (old name `convert-automation`) — export a Cursor Automation into a BDK
 * project.
 *
 * Fetches the automation's workflow from the backend export endpoint
 * (Bearer user API key, same credential chain as deploy), runs the pure
 * converter, writes the converted files (wx — existing files are kept),
 * fills in the init scaffold around them, and installs npm dependencies
 * (like `init`). MCP servers convert to Cursor-account connections resolved
 * at runtime (no URLs or credentials in the project; authorization is
 * managed in Cursor, dashboard → MCP). The generated project is NEVER
 * imported/executed here — it embeds server-derived data, so checking it is
 * left to an explicit `validate` next step the user runs after review.
 * Exit 0 even with warnings; nonzero only for bad args, auth/fetch
 * failures, or filesystem write failures.
 */
import { existsSync } from "node:fs";
import { rm } from "node:fs/promises";
import { join, resolve } from "node:path";
import { convertWorkflow } from "./convert-automation/convert-workflow.js";
import { slugify } from "./slug.js";
import { cursorExternalApiUrl, resolveApiKey, SIGN_IN_HINT } from "./cursor/credentials.js";
import { AgentServeDeployClient, DeployApiError } from "./deploy-client.js";
import { CLI_COMMAND_NAME as CLI } from "./distribution.js";
import { formatCdCommand, initProject, installScaffoldDependencies, writeNewFile, } from "./init-project.js";
import { projectPath, resolveProjectRoot } from "./project-layout.js";
import { stdoutPalette } from "./terminal-style.js";
const UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
/**
 * Extract the automation uuid from a dashboard URL
 * (`/automations/<uuid>` or `/custom-agents/<uuid>`, any origin — dev
 * hosts included) or a bare uuid. Undefined when nothing matches.
 */
export function parseAutomationRef(input) {
    const trimmed = input.trim();
    if (UUID_PATTERN.test(trimmed)) {
        return trimmed.toLowerCase();
    }
    let parsed;
    try {
        parsed = new URL(trimmed);
    }
    catch {
        return undefined;
    }
    if (parsed.protocol !== "http:" && parsed.protocol !== "https:") {
        return undefined;
    }
    const segments = parsed.pathname.split("/").filter((s) => s !== "");
    if (segments.length !== 2) {
        return undefined;
    }
    const [kind, uuid] = segments;
    if (kind !== "automations" && kind !== "custom-agents") {
        return undefined;
    }
    if (uuid === undefined || !UUID_PATTERN.test(uuid)) {
        return undefined;
    }
    return uuid.toLowerCase();
}
export async function cmdConvertAutomation(options) {
    const out = options.out ?? ((text) => void process.stdout.write(text));
    const err = options.err ?? ((text) => void process.stderr.write(text));
    const json = options.json === true;
    // Failures stay machine-readable under --json (stderr keeps the prose).
    const fail = (message) => {
        if (json) {
            out(`${JSON.stringify({ ok: false, error: message })}\n`);
        }
        err(`${message}\n`);
        return 1;
    };
    if (options.url === undefined || options.url.trim() === "") {
        return fail(`Usage: ${CLI} init [dir] --from automation:<url-or-uuid> [--json]`);
    }
    const uuid = parseAutomationRef(options.url);
    if (uuid === undefined) {
        return fail(`Could not parse ${JSON.stringify(options.url)} — expected an automation URL (https://cursor.com/automations/<uuid> or .../custom-agents/<uuid>) or a bare uuid.`);
    }
    const resolved = await resolveApiKey({ apiKey: options.apiKey });
    if (resolved === undefined) {
        return fail(`Not signed in to Cursor. ${SIGN_IN_HINT}`);
    }
    const client = new AgentServeDeployClient({
        backendUrl: cursorExternalApiUrl(),
        apiKey: resolved.apiKey,
        fetchImpl: options.fetchImpl,
    });
    let payload;
    try {
        payload = await client.exportAutomation({ uuid });
    }
    catch (error) {
        if (error instanceof DeployApiError) {
            return fail(error.message);
        }
        throw error;
    }
    const displayDir = options.dir ?? `./${slugify(payload.automation.name, "automation")}`;
    const rootDir = resolve(options.cwd ?? process.cwd(), displayDir);
    const projectRoot = resolveProjectRoot(rootDir);
    const result = convertWorkflow({
        automation: payload.automation,
        workflow: payload.workflow,
        mcpServers: payload.mcpServers,
        exportedAt: new Date().toISOString(),
        projectRoot,
    });
    if (options.dryRun === true) {
        const planned = await planProjectFiles(rootDir, result, projectRoot);
        if (json) {
            out(`${JSON.stringify({ dryRun: true, directory: rootDir, files: planned, warnings: result.warnings }, null, 2)}\n`);
        }
        else {
            out(`Dry run: would write the converted automation into ${displayDir}, add the init scaffold around it, and run npm install.\n` +
                planned
                    .map((file) => `  ${file.action === "create" ? "create" : "keep  "} ${file.path}\n`)
                    .join("") +
                "Nothing was written.\n");
        }
        return 0;
    }
    let files;
    try {
        files = await writeProjectFiles(rootDir, result, projectRoot);
    }
    catch (error) {
        return fail(`Could not write project files under ${rootDir}: ${describe(error)}`);
    }
    // Same npm install as `init`, so the printed `validate` / `dev` next steps
    // work immediately. Failure (npm exit or spawn error) is loud but never
    // fails the conversion.
    const install = options.installImpl ?? installScaffoldDependencies;
    if (!json) {
        out("\nInstalling npm packages\n");
    }
    let installed;
    try {
        installed = await install(rootDir, {
            stdio: json ? "pipe" : "inherit",
        });
    }
    catch (error) {
        installed = { ok: false, exitCode: -1, stderr: describe(error) };
    }
    if (!installed.ok && !json) {
        const reason = installed.stderr.trim() || `exit ${installed.exitCode}`;
        err(`npm install failed (${reason}); run \`npm install\` in ${displayDir} before \`${CLI} dev\`.\n`);
    }
    if (json) {
        out(`${JSON.stringify({
            ok: true,
            directory: rootDir,
            files: files.map(({ path, action }) => ({ path, action })),
            warnings: result.warnings,
            setupSteps: result.setupSteps,
            installed: installed.ok,
            installError: installed.ok
                ? null
                : installed.stderr.trim() || `npm install exited ${installed.exitCode}`,
            mcpConnections: result.mcpConnections.map((connection) => ({
                name: connection.name,
                kind: connection.kind,
            })),
        }, null, 2)}\n`);
        return 0;
    }
    out(renderSummary({
        automationName: payload.automation.name,
        displayDir,
        rootDir,
        cwd: options.cwd ?? process.cwd(),
        files,
        result,
    }));
    return 0;
}
/**
 * Converter files first (wx — existing files are kept), then the init
 * scaffold fills in around them with the same skip-existing semantics.
 */
async function writeProjectFiles(rootDir, result, projectRoot) {
    const entries = [];
    const converterPaths = new Set();
    for (const file of result.files) {
        converterPaths.add(file.path);
        entries.push({
            path: file.path,
            action: await writeNewFile(rootDir, file),
        });
    }
    const init = await initProject({ dir: rootDir });
    const scaffold = scaffoldEntries(init, converterPaths, projectRoot);
    for (const dropPath of scaffold.drop) {
        await rm(join(rootDir, dropPath));
    }
    entries.push(...scaffold.keep);
    return entries;
}
/**
 * The `--dry-run` twin of `writeProjectFiles`: the same file list with
 * create/exist for each path, converter files and the init scaffold. It
 * writes nothing.
 */
async function planProjectFiles(rootDir, result, projectRoot) {
    const entries = result.files.map((file) => ({
        path: file.path,
        action: existsSync(join(rootDir, file.path)) ? "exist" : "create",
    }));
    const converterPaths = new Set(result.files.map((file) => file.path));
    const init = await initProject({ dir: rootDir, dryRun: true });
    entries.push(...scaffoldEntries(init, converterPaths, projectRoot).keep);
    return entries;
}
/**
 * Split the init scaffold into the entries to report and the new files to
 * remove. Converter files win over scaffold files at the same path. Scaffold
 * files that make sense in a fresh `init` but not in an exported automation
 * are dropped when init created them: the default memory hook (only when the
 * automation had memory enabled — the converter emits its own copy then) and
 * the echo demo tool.
 */
function scaffoldEntries(init, converterPaths, projectRoot) {
    const drop = [
        projectPath(projectRoot, "hooks/memory.ts"),
        projectPath(projectRoot, "tools/echo.ts"),
    ].filter((scaffoldPath) => !converterPaths.has(scaffoldPath) && init.created.includes(scaffoldPath));
    const keep = init.files.filter((entry) => !converterPaths.has(entry.path) && !drop.includes(entry.path));
    return { keep, drop };
}
function renderSummary(args) {
    const c = stdoutPalette();
    const lines = [];
    lines.push("");
    lines.push(`Converted "${args.automationName}" → ${args.displayDir}`);
    lines.push("");
    let anyExisting = false;
    for (const file of args.files) {
        if (file.path.endsWith(".gitkeep")) {
            continue;
        }
        anyExisting ||= file.action === "exist";
        lines.push(c.dim(`${file.action.padStart(12)}  ${file.path}`));
    }
    if (anyExisting) {
        lines.push(c.dim(`\n  "exist" files already existed and were kept as-is.`));
    }
    const warnings = args.result.warnings;
    if (warnings.length > 0) {
        lines.push("");
        lines.push("Warnings:");
        for (const warning of warnings) {
            lines.push(`  - ${warning}`);
        }
    }
    if (args.result.setupSteps.length > 0) {
        lines.push("");
        lines.push("Setup steps:");
        for (const [index, step] of args.result.setupSteps.entries()) {
            lines.push(`  ${index + 1}. ${step}`);
        }
    }
    if (args.result.mcpConnections.length > 0) {
        lines.push("");
        lines.push("MCP connections:");
        for (const connection of args.result.mcpConnections) {
            lines.push(`  - ${connection.name}: ${connectionStatus(connection)}`);
        }
    }
    lines.push("");
    lines.push("Next steps:");
    const cd = formatCdCommand(args.cwd, args.rootDir);
    const steps = [...(cd === undefined ? [] : [cd]), `${CLI} validate`, `${CLI} dev`];
    for (const [index, step] of steps.entries()) {
        lines.push(`  ${index + 1}. ${step}`);
    }
    lines.push("");
    return `${lines.join("\n")}\n`;
}
function connectionStatus(connection) {
    if (connection.kind === "cursorAccount") {
        return "resolved from your Cursor account at runtime — manage authorization in Cursor (dashboard → MCP)";
    }
    return "needs manual setup — see the stub file and warnings above";
}
function describe(error) {
    return error instanceof Error ? error.message : String(error);
}
